import re

from moler.exceptions import ParsingDone, CommandFailure

from ta_moler.cmd.egate.generictabcontent import GenericTabContent

__author__ = 'Adrianna Pienkowska'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'adrianna.pienkowska@nokia.com'


class MbmsgwDisp(GenericTabContent):
    """Mbmsgwdisp command class."""

    def __init__(self, connection, mbms_gw__id=None, prompt=None, newline_chars=None, runner=None):
        """
        Mbmsgwdisp command.

        :param connection: moler connection to device, terminal when command is executed.
        :param mbms_gw__id: id of mbms_gw.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(MbmsgwDisp, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.mbms_gw__id = mbms_gw__id

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'mbmsgw_disp'
        if self.mbms_gw__id:
            cmd = f'{cmd} id={str(self.mbms_gw__id)}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_not_configured(line)
            except ParsingDone:
                pass
        return super(MbmsgwDisp, self).on_new_line(line, is_full_line)

    _re_configured = re.compile(r"is not configured")

    def _parse_not_configured(self, line):
        if self._regex_helper.search_compiled(MbmsgwDisp._re_configured, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone


